    41	function find_user_by_username(string $username): ?array
    42	{
    43	  $username = normalize_identity($username);
    44	  if ($username === '') {
    45	    return null;
    46	  }
    47	
    48	  $data = storage_read();
    49	  foreach ($data['users'] as $user) {
    50	    if (!is_array($user)) {
    51	      continue;
    52	    }
    53	    $candidate = normalize_identity((string) ($user['username'] ?? ''));
    54	    if ($candidate === $username) {
    55	      return $user;
    56	    }
    57	  }
    58	  return null;
    59	}
