    61	/**
    62	 * Persist user changes.
    63	 *
    64	 * @param array<string,mixed> $newUser
    65	 */
    66	function save_user(array $newUser): void
    67	{
    68	  $data = storage_read();
    69	  foreach ($data['users'] as $idx => $user) {
    70	    if (!is_array($user)) {
    71	      continue;
    72	    }
    73	    if (($user['id'] ?? '') === ($newUser['id'] ?? null)) {
    74	      $newUser['updated_at'] = date('c');
