   138	/**
   139	 * Record failed login attempt.
   140	 */
   141	function record_failed_login(string $identity): void
   142	{
   143	  $identity = normalize_identity($identity);
   144	  $data = storage_read();
   145	  $data['login_attempts'][] = [
   146	    'identity' => $identity,
   147	    'ip' => client_ip(),
   148	    'time' => time(),
   149	  ];
   150	  storage_write($data);
   151	}
   152	
   153	/**
   154	 * Clear attempts by identity and ip after successful login.
   155	 */
   156	function clear_login_attempts(string $identity): void
   157	{
   158	  $identity = normalize_identity($identity);
   159	  $ip = client_ip();
   160	  $data = storage_read();
   161	  $filtered = [];
   162	  foreach ($data['login_attempts'] as $entry) {
   163	    if (!is_array($entry)) {
   164	      continue;
   165	    }
   166	    $entryIdentity = (string) ($entry['identity'] ?? '');
   167	    $entryIp = (string) ($entry['ip'] ?? '');
   168	    if ($entryIdentity === $identity || $entryIp === $ip) {
   169	      continue;
   170	    }
   171	    $filtered[] = $entry;
   172	  }
   173	  $data['login_attempts'] = $filtered;
   174	  storage_write($data);
   175	}
   176	
   177	/**
   178	 * Attempt login with username and password.
   179	 *
   180	 * @return array{ok:bool,code:string,message:string,user?:array<string,mixed>}
   181	 */
   182	function attempt_login(string $username, string $password): array
   183	{
   184	  $identity = trim($username);
   185	  $lock = lock_status($identity);
   186	  if ($lock['locked']) {
   187	    return [
   188	      'ok' => false,
   189	      'code' => 'locked',
   190	      'message' => 'Tài khoản đang tạm khóa. Vui lòng thử lại sau ' . human_seconds($lock['remaining']) . '.',
   191	    ];
   192	  }
   193	
   194	  $user = find_user_by_username($identity);
   195	  if ($user === null || empty($user['is_active'])) {
   196	    record_failed_login($identity);
   197	    return [
   198	      'ok' => false,
   199	      'code' => 'invalid_credentials',
   200	      'message' => 'Sai tên đăng nhập hoặc mật khẩu.',
   201	    ];
   202	  }
   203	
   204	  $hash = (string) ($user['password_hash'] ?? '');
   205	  if ($hash === '' || !password_verify($password, $hash)) {
   206	    record_failed_login($identity);
   207	    return [
   208	      'ok' => false,
   209	      'code' => 'invalid_credentials',
   210	      'message' => 'Sai tên đăng nhập hoặc mật khẩu.',
   211	    ];
   212	  }
   213	
   214	  clear_login_attempts($identity);
   215	
   216	  session_regenerate_id(true);
   217	  $_SESSION['auth'] = [
   218	    'user_id' => $user['id'],
   219	    'username' => $user['username'],
   220	    'display_name' => $user['display_name'],
   221	    'role' => $user['role'],
   222	    'must_change_password' => (bool) ($user['must_change_password'] ?? false),
   223	    'login_at' => date('c'),
   224	    'last_seen' => time(),
   225	  ];
   226	
   227	  $user['last_login_at'] = date('c');
   228	  save_user($user);
   229	
   230	  append_audit_log([
   231	    'event' => 'auth.login.success',
   232	    'username' => $user['username'],
   233	    'user_id' => $user['id'],
   234	    'role' => $user['role'],
   235	  ]);
   236	
   237	  return [
   238	    'ok' => true,
   239	    'code' => 'ok',
   240	    'message' => 'Đăng nhập thành công.',
   241	    'user' => $user,
   242	  ];
   243	}
   244	
   245	/**
   246	 * Logout current session.
   247	 */
   248	function logout_current_user(): void
   249	{
   250	  $auth = $_SESSION['auth'] ?? null;
   251	  if (is_array($auth) && isset($auth['username'])) {
   252	    append_audit_log([
   253	      'event' => 'auth.logout',
   254	      'username' => (string) $auth['username'],
   255	      'user_id' => (string) ($auth['user_id'] ?? ''),
   256	      'role' => (string) ($auth['role'] ?? ''),
   257	    ]);
   258	  }
   259	
   260	  $_SESSION = [];
   261	  if (ini_get('session.use_cookies')) {
   262	    $params = session_get_cookie_params();
   263	    setcookie(session_name(), '', time() - 42000, $params['path'] ?? '/', $params['domain'] ?? '', (bool) ($params['secure'] ?? false), (bool) ($params['httponly'] ?? true));
   264	  }
   265	  session_destroy();
   266	}
   267	
   268	/**
   269	 * Is there an authenticated user.
   270	 */
   271	function is_authenticated(): bool
   272	{
   273	  $auth = $_SESSION['auth'] ?? null;
   274	  if (!is_array($auth) || empty($auth['user_id'])) {
   275	    return false;
   276	  }
   277	
   278	  $lastSeen = (int) ($auth['last_seen'] ?? 0);
   279	  if ($lastSeen <= 0 || (time() - $lastSeen) > ADMIN_SESSION_TTL) {
   280	    logout_current_user();
   281	    return false;
   282	  }
   283	
   284	  $_SESSION['auth']['last_seen'] = time();
   285	  return true;
   286	}
   287	
   288	/**
   289	 * Get current user session payload.
   290	 *
   291	 * @return array<string,mixed>|null
   292	 */
   293	function current_user(): ?array
   294	{
   295	  if (!is_authenticated()) {
   296	    return null;
   297	  }
   298	  $auth = $_SESSION['auth'] ?? null;
   299	  return is_array($auth) ? $auth : null;
   300	}
   301	
   302	/**
   303	 * Require authentication, redirect to login when missing.
   304	 */
   305	function require_auth(): void
   306	{
   307	  if (is_authenticated()) {
   308	    return;
   309	  }
   310	  flash_set('warning', 'Vui lòng đăng nhập để tiếp tục.');
   311	  redirect_to(admin_url('login.php'));
   312	}
   313	
   314	/**
   315	 * Require specific role.
   316	 *
   317	 * @param array<int,string> $roles
   318	 */
   319	function require_role(array $roles): void
   320	{
   321	  require_auth();
   322	  $user = current_user();
   323	  $role = (string) ($user['role'] ?? '');
   324	  if (in_array($role, $roles, true)) {
