     4	/**
     5	 * Resolve admin base path from current request (supports subfolder deploy).
     6	 * Example:
     7	 * - /admin/login.php -> /admin
     8	 * - /Ketoandieutam.com/admin/login.php -> /Ketoandieutam.com/admin
     9	 */
    10	function admin_base_path_uri(): string
    11	{
    12	  $scriptName = str_replace('\\', '/', (string) ($_SERVER['SCRIPT_NAME'] ?? '/admin/index.php'));
    13	  $dir = dirname($scriptName);
    14	  if ($dir === '' || $dir === '.') {
    15	    $dir = '/admin';
    16	  }
    17	  $dir = '/' . trim($dir, '/');
    18	  return $dir === '//' ? '/' : $dir;
    19	}
    20	
    21	/**
    22	 * Validate this request is really under /admin path.
    23	 * Prevent accidental redirects to admin login from non-admin URLs.
    24	 */
    25	function is_admin_request_context(): bool
    26	{
    27	  if (PHP_SAPI === 'cli') {
    28	    return true;
    29	  }
    30	  $scriptName = str_replace('\\', '/', (string) ($_SERVER['SCRIPT_NAME'] ?? ''));
    31	  if ($scriptName === '') {
    32	    return false;
    33	  }
    34	  return str_contains($scriptName, '/admin/') || str_ends_with($scriptName, '/admin');
    35	}
    36	
    37	/**
    38	 * Reject non-admin context requests.
    39	 */
    40	function enforce_admin_request_context_or_reject(): void
    41	{
